internal val TIME_ZONE_CITIES_ML: String =
    "root\u001F05അബിദ്‌ജാൻ‌\u001Eആക്ര\u001Eഅഡിസ് അബാബ\u001Eഅൾജിയേഴ്‌സ്\u001Eഅസ്‍മാര\u001Eബമാകോ\u001Eബംഗുയി\u001Eബഞ്ചുൽ\u001Eബിസ്സാവു\u001Eബ്ലാണ്ടെയർ‌\u001Eബ്രാസവിൽ\u001Eബുജും‌ബുര\u001Eകെയ്‌റോ\u001Eകാസബ്ലാങ്ക\u001Eക്യൂട്ട\u001Eകൊണാക്രി\u001Eഡാക്കർ‌\u001Eദാർ എസ് സലാം\u001Eദിജിബൗട്ടി\u001Eഡൗല\u001Eഎൽ‌ ഐയുൻ‌\u001Eഫ്രീടൗൺ\u001Eഗാബറോൺ\u001Eഹരാരെ\u001Eജോഹന്നാസ്ബർ‌ഗ്\u001Eജുബ\u001Eകമ്പാല\u001Eഖാർ‌തൌം\u001Eകിഗാലി\u001Eകിൻഷാസ\u001Eലാഗോസ്\u001Eലിബ്രെവില്ല\u001Eലോം\u001Eലുവാൻഡ\u001Eലൂബുംബാഷി\u001Eലുസാക\u001Eമലാബോ\u001Eമാപ്യുട്ടോ\u001Eമസേറു\u001Eമബാബെയ്‌ൻ‌\u001Eമൊഗാദിഷു\u001Eമൺ‌റോവിയ\u001Eനയ്‌റോബി\u001Eജമെന\u001Eനിയാമി\u001Eനൗവാക്‌ഷോട്ട്\u001Eഔഗാദൗഗൗ\u001Eപോർ‌ട്ടോ-നോവോ\u001Eസാവോ ടോം‌\u001Eട്രിപൊളി\u001Eട്യൂണിസ്\u001Eവിൻഡ്‌ഹോക്\u001Eഅഡാക്\u001Eആങ്കറേജ്\u001Eആൻഗ്വില്ല\u001Eആൻറിഗ്വ\u001Eഅറഗ്വൈന\u001Eലാ റിയോജ\u001Eറിയോ ഗ്യാലഗോസ്\u001Eസാൽട്ട\u001Eസാൻ ജുവാൻ\u001Eസാൻ ലൂയിസ്\u001Eറ്റുകുമാൻ\u001Eഉഷിയ\u001Eഅറൂബ\u001Eഅസൻ‌ഷ്യൻ‌\u001Eബഹിയ\u001Eബഹിയ ബൻഡാരസ്\u001Eബാർബഡോസ്\u001Eബെലം\u001Eബെലീസ്\u001Eബ്ലാങ്ക് സാബ്ലോൺ\u001Eബോവ വിസ്റ്റ\u001Eബൊഗോട്ട\u001Eബൊയ്സി\u001Eബ്യൂണസ് ഐറിസ്\u001Eകേംബ്രിഡ്‌ജ് ബേ\u001Eക്യാമ്പോ ഗ്രാൻഡെ\u001Eകാൻകൂൺ\u001Eകരാക്കസ്\u001E‍ക്യാറ്റമാർക്ക\u001Eകയീൻ‌\u001Eകേമാൻ\u001Eചിക്കാഗോ\u001Eചിഹ്വാഹ\u001Eസിയുഡാഡ് ഹുവാരസ്\u001Eഏറ്റികോക്കൺ\u001Eകോർഡോബ\u001Eകോസ്റ്റ റിക്ക\u001Eകൊയൈകേ\u001Eക്രെസ്റ്റൺ\u001Eകുയ്‌ബ\u001Eകുറാക്കാവോ\u001Eഡാൻമാർക്ക്ഷാവ്ൻ\u001Eഡോവ്സൺ\u001Eഡോവ്സൺ ക്രീക്ക്\u001Eഡെൻ‌വർ\u001Eഡെട്രോയിറ്റ്\u001Eഡൊമിനിക്ക\u001Eഎഡ്മോൺടൺ\u001Eയെറുനീപ്പെ\u001Eഎൽ സാൽ‌വദോർ\u001Eഫോർട്ട് നെൽസൺ\u001Eഫോർട്ടലീസ\u001Eഗ്ലെയ്സ് ബേ\u001Eനൂക്ക്\u001Eഗൂസ് ബേ\u001Eഗ്രാൻഡ് ടർക്ക്\u001Eഗ്രനേഡ\u001Eഗ്വാഡലൂപ്പ്\u001Eഗ്വാട്ടിമാല\u001Eഗുവായക്വിൽ\u001Eഗയാന\u001Eഹാലിഫാക്സ്\u001Eഹവാന\u001Eഹെർമോസില്ലോ\u001Eനോക്സ്, ഇൻഡ്യാന\u001Eമരെങ്കോ, ഇൻഡ്യാന\u001Eപീറ്റേഴ്സ്ബർഗ്, ഇൻഡ്യാന\u001Eറ്റെൽ സിറ്റി, ഇൻഡ്യാന\u001Eവിവെയ്, ഇൻഡ്യാന\u001Eവിൻസെൻസ്, ഇൻഡ്യാന\u001Eവിനാമാക്, ഇൻഡ്യാന\u001Eഇൻഡ്യാനാപോളിസ്\u001Eഇനുവിക്\u001Eഇഖാലിത്\u001Eജമൈക്ക\u001Eജുജുയ്\u001Eജൂനോ\u001Eമോണ്ടിസെല്ലോ, കെന്റക്കി\u001Eകാർലൻഡിജെക്ക്\u001Eലാ പാസ്\u001Eലിമ\u001Eലോസ് എയ്ഞ്ചലസ്\u001Eലൂയിസ്‌വില്ലെ\u001Eലോവർ പ്രിൻസസ് ക്വാർട്ടർ\u001Eമാസിയോ\u001Eമനാഗ്വ\u001Eമനൗസ്\u001Eമാരിഗോ\u001Eമാർട്ടിനിക്\u001Eമറ്റാമൊറോസ്\u001Eമസറ്റ്‌ലാൻ\u001Eമെൻഡോസ\u001Eമെനോമിനീ\u001Eമെരിഡ\u001Eമെഡ്‌ലകട്‌ലെ\u001Eമെക്സിക്കോ സിറ്റി\u001Eമിക്വലൻ\u001Eമോംഗ്‌ടൻ\u001Eമോണ്ടെറി\u001Eമൊണ്ടെ‌വീഡിയോ\u001Eമൊണ്ടെസരത്ത്\u001Eനാസൗ\u001Eന്യൂയോർക്ക്\u001Eനോം\u001Eനൊറോന\u001Eബ്യൂല, വടക്കൻ ഡെക്കോട്ട\u001Eസെന്റർ, വടക്കൻ ഡെക്കോട്ട\u001Eന്യൂ സെയ്‌ലം, വടക്കൻ ഡെക്കോട്ട\u001Eഒജിൻഗ\u001Eപനാമ\u001Eപരാമാരിബോ\u001Eഫീനിക്സ്\u001Eപോർട്ടോപ്രിൻസ്\u001Eപോർ‌ട്ട് ഓഫ് സ്‌പെയിൻ‌\u001Eപോർട്ടോ വെല്ലോ\u001Eപ്യൂർട്ടോ റിക്കോ\u001Eപുന്റ അരീനസ്\u001Eറാങ്കിൻ ഇൻലെറ്റ്\u001Eറെസീഫെ\u001Eറിജീന\u001Eറെസല്യൂട്ട്\u001Eറിയോ ബ്രാങ്കോ\u001Eസാന്ററെം\u001Eസാന്റിയാഗോ\u001Eസാന്തോ ഡോമിംഗോ\u001Eസാവോപോളോ\u001Eഇറ്റ്വാഖ്വാർടൂർമിറ്റ്\u001Eസിറ്റ്‌കാ\u001Eസെന്റ് ബർത്തലെമി\u001Eസെന്റ് ജോൺസ്\u001Eസെന്റ് കിറ്റ്സ്\u001Eസെന്റ് ലൂസിയ\u001Eസെന്റ് തോമസ്\u001Eസെന്റ് വിൻസെന്റ്\u001Eസ്വിഫ്‌റ്റ് കറന്റ്\u001Eടെഗൂസിഗാൽപ\u001Eതൂളി\u001Eതിയുവാന\u001Eടൊറന്റോ\u001Eടോർ‌ട്ടോള\u001Eവാൻ‌കൂവർ\u001Eവൈറ്റ്ഹോഴ്സ്\u001Eവിന്നിപെഗ്\u001Eയാകുറ്റാറ്റ്\u001Eകാസെ\u001Eഡെയ്‌വിസ്\u001Eഡ്യൂമണ്ട് ഡി യുർവിൽ\u001Eമക്വയറി\u001Eമാവ്സൺ\u001Eമാക്മർഡോ\u001Eപാമർ\u001Eറൊതീറ\u001Eസ്യോവ\u001Eട്രോൾ\u001Eവോസ്റ്റോക്\u001Eലംഗ്‍യെർബിൻ\u001Eഏദെൻ\u001Eഅൽമാട്ടി\u001Eഅമ്മാൻ‌\u001Eഅനാഡിർ\u001Eഅക്തൗ\u001Eഅഖ്‌തോബ്\u001Eആഷ്‌ഗാബട്ട്\u001Eഅറ്റിറോ\u001Eബാഗ്‌ദാദ്\u001Eബഹ്റിൻ\u001Eബാക്കു\u001Eബാങ്കോക്ക്\u001Eബർണോൽ\u001Eബെയ്‌റൂട്ട്\u001Eബിഷ്‌കേക്\u001Eബ്രൂണൈ\u001Eകൊൽ‌ക്കത്ത\u001Eചീറ്റ\u001Eകൊളം‌ബോ\u001Eദമാസ്കസ്\u001Eധാക്ക\u001Eദിലി\u001Eദുബായ്\u001Eദുഷൻ‌ബെ\u001Eഫാമഗുസ്‌റ്റ\u001Eഗാസ\u001Eഹെബ്‌റോൺ\u001Eഹോങ്കോംഗ്\u001Eഹോഡ്\u001Eഇർകസ്ക്\u001Eജക്കാർത്ത\u001Eജയപുര\u001Eജെറുസലേം\u001Eകാബൂൾ\u001Eകാംചട്ക\u001Eകറാച്ചി\u001Eകാഠ്‌മണ്ഡു\u001Eകാൻഡിഗ\u001Eക്രാസ്നോയാസ്ക്\u001Eക്വാലലം‌പൂർ‌‌\u001Eകുചിങ്\u001Eകുവൈത്ത്\u001Eമക്കാവു\u001Eമഗഡാൻ\u001Eമകസ്സർ\u001Eമനില\u001Eമസ്കറ്റ്\u001Eനിക്കോഷ്യ\u001Eനോവോകുസെൻസ്‌ക്\u001Eനൊവോസിബിർസ്ക്\u001Eഒംസ്ക്\u001Eഓറൽ\u001Eഫെനോം പെൻ\u001Eപൊന്റിയാനക്\u001Eപ്യോംഗ്‌യാംഗ്\u001Eഖത്തർ\u001Eകോസ്റ്റനേ\u001Eഖിസിലോർഡ\u001Eറങ്കൂൺ‌\u001Eറിയാദ്\u001Eഹോ ചി മിൻ സിറ്റി\u001Eസഖാലിൻ\u001Eസമർക്കന്ദ്\u001Eസോൾ\u001Eഷാങ്‌ഹായി\u001Eസിംഗപ്പൂർ\u001Eസ്രിഡ്‌നികോളിംസ്ക്\u001Eതായ്‌പെയ്\u001Eതാഷ്‌ക്കന്റ്\u001Eതിബിലിസി\u001Eടെഹ്‌റാൻ‌\u001Eതിംഫു\u001Eടോക്കിയോ\u001Eടോംസ്ക്\u001Eഉലാൻബാത്തർ\u001Eഉറുംഖി\u001Eയുസ്-നേര\u001Eവെന്റിയാൻ\u001Eവ്ളാഡിവോസ്റ്റോക്\u001Eയാക്കറ്റ്സ്‌ക്\u001Eയാകാറ്റെറിൻബർഗ്\u001Eയേരവൻ‌\u001Eഅസോറസ്\u001Eബർമുഡ\u001Eക്യാനറി\u001Eകേപ് വെർദെ\u001Eഫെറോ\u001Eമഡെയ്റ\u001Eറേയ്‌ജാവിക്\u001Eദക്ഷിണ ജോർജിയ\u001Eസെന്റ് ഹെലെന\u001Eസ്റ്റാൻ‌ലി\u001Eഅഡിലെയ്‌ഡ്\u001Eബ്രിസ്‌ബെയിൻ\u001Eബ്രോക്കൺ ഹിൽ\u001Eഡാർവിൻ\u001Eയൂക്ല\u001Eഹൊബാർട്ട്\u001Eലിൻഡെമാൻ\u001Eലോഡ് ഹോവ്\u001Eമെൽബൺ\u001Eപെർത്ത്\u001Eസിഡ്നി\u001Eഅജ്ഞാത നഗരം\u001Eആം‌സ്റ്റർ‌ഡാം\u001Eഅണ്ടോറ\u001Eഅസ്‌ട്രഖാൻ\u001Eഏതൻ‌സ്\u001Eബെൽഗ്രേഡ്\u001Eബെർ‌ലിൻ‌\u001Eബ്രാട്ടിസ്‍ലാവ\u001Eബ്രസ്സൽ‌സ്\u001Eബുച്ചാറെസ്റ്റ്\u001Eബുഡാപെസ്റ്റ്\u001Eബുസിൻജൻ\u001Eചിസിനാവു\u001Eകോപ്പൻ‌ഹേഗൻ‌\u001Eഡബ്ലിൻ\u001Eജിബ്രാൾട്ടർ\u001Eഗേൺസേ\u001Eഹെൽ‌സിങ്കി\u001Eഐൽ‌ ഓഫ് മാൻ‌\u001Eഇസ്താം‌ബുൾ‌\u001Eജേഴ്‌സി\u001Eകലിനിൻഗ്രാഡ്\u001Eകീവ്\u001Eകിറോ\u001Eലിസ്‌ബൺ‌\u001Eലുബ്‍ലിയാന\u001Eലണ്ടൻ‌\u001Eലക്‌സംബർഗ്\u001Eമാഡ്രിഡ്\u001Eമാൾട്ട\u001Eമരിയാഹാമൻ\u001Eമിൻ‌സ്ക്\u001Eമൊണാക്കോ\u001Eമോസ്കോ\u001Eഓസ്ലോ\u001Eപാരീസ്\u001Eപൊഡ്‍ഗൊറിസ\u001Eപ്രാഗ്\u001Eറിഗ\u001Eറോം\u001Eസമാറ\u001Eസാൻ മാരിനോ\u001Eസരയേവോ\u001Eസരാറ്റോവ്\u001Eസിംഫെറോപോൾ\u001Eസ്കോപ്പിയെ\u001Eസോഫിയ\u001Eസ്റ്റോക്ക്ഹോം\u001Eടാലിൻ‌\u001Eടിരാനെ\u001Eഉല്ല്യാനോവ്‌സ്‌ക്\u001Eവാദുസ്\u001Eവത്തിക്കാൻ\u001Eവിയന്ന\u001Eവിൽ‌നിയസ്\u001Eവോൾഗോഗ്രാഡ്\u001Eവാർസോ\u001Eസാക്രെബ്\u001Eസൂറിച്ച്\u001Eഅൻറാനനറിവോ\u001Eചാഗോസ്\u001Eക്രിസ്തുമസ്\u001Eകോക്കോസ്\u001Eകൊമോറോ\u001Eകെർഗുലെൻ\u001Eമാഹി\u001Eമാലിദ്വീപ്\u001Eമൗറീഷ്യസ്\u001Eമയോട്ടി\u001Eറീയൂണിയൻ\u001Eആപിയ\u001Eഓക്ക്‌ലാന്റ്\u001Eബോഗൺവില്ലെ\u001Eചാത്തം\u001Eഈസ്റ്റർ\u001Eഇഫാതെ\u001Eകാന്റൺ ദ്വീപ്\u001Eഫക്കാവോഫോ\u001Eഫിജി\u001Eഫുണാഫുട്ടി\u001Eഗാലപ്പാഗോസ്\u001Eഗാമ്പിയർ\u001Eഗ്വാഡൽകനാൽ\u001Eഗ്വാം\u001Eഹോണലൂലു\u001Eകിരിറ്റിമാറ്റി\u001Eകൊസ്രേ\u001Eക്വാജലെയ്ൻ\u001Eമജൂറോ\u001Eമാർക്യുസാസ്\u001Eമ